import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Loader from './Loader';
import '../styles/NewsPage.css';

const NewsPage = () => {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeFilter, setActiveFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  // Define news categories
  const categories = [
    { id: 'all', name: 'Semua' },
    { id: 'market', name: 'Pasar Saham' },
    { id: 'economy', name: 'Ekonomi' },
    { id: 'business', name: 'Bisnis' },
    { id: 'finance', name: 'Keuangan' },
    { id: 'technology', name: 'Teknologi' }
  ];

  // Fetch news data when component mounts
  useEffect(() => {
    const fetchNews = async () => {
      setLoading(true);
      try {
        // Replace with your actual API endpoint
        const response = await axios.get('http://localhost:5000/news');
        if (response.data && Array.isArray(response.data)) {
          // Sort news by date (newest first)
          const sortedNews = response.data.sort((a, b) => 
            new Date(b.publishedAt) - new Date(a.publishedAt)
          );
          setNews(sortedNews);
        }
      } catch (error) {
        console.error('Error fetching news:', error);
        // Provide fallback data in case API fails
        setNews(sampleNewsData);
      } finally {
        setLoading(false);
      }
    };

    fetchNews();
  }, []);

  // Filter news based on active category and search term
  const filteredNews = news.filter(item => {
    const matchesCategory = activeFilter === 'all' || item.category === activeFilter;
    const matchesSearch = !searchTerm || 
      item.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.description.toLowerCase().includes(searchTerm.toLowerCase());
    
    return matchesCategory && matchesSearch;
  });

  // Format date to locale string
  const formatDate = (dateString) => {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString('id-ID', options);
  };

  // Handle category filter change
  const handleFilterChange = (categoryId) => {
    setActiveFilter(categoryId);
  };

  // Handle search input change
  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  return (
    <div className="news-container">
      <section className="news-hero-section">
        <div className="news-hero-content">
          <h1>Berita & Analisis Pasar</h1>
          <p>Dapatkan informasi terkini seputar pasar modal, ekonomi, dan bisnis</p>
        </div>
      </section>

      <section className="news-filter-section">
        <div className="news-search">
          <input
            type="text"
            placeholder="Cari berita..."
            value={searchTerm}
            onChange={handleSearchChange}
            className="search-input"
          />
          <button className="search-button">
            <i className="search-icon">🔍</i>
          </button>
        </div>

        <div className="category-filters">
          {categories.map(category => (
            <button
              key={category.id}
              className={`category-filter-btn ${activeFilter === category.id ? 'active' : ''}`}
              onClick={() => handleFilterChange(category.id)}
            >
              {category.name}
            </button>
          ))}
        </div>
      </section>

      <section className="news-content-section">
        <div className="section-header">
          <h2 className="section-title">Berita Terbaru</h2>
          <div className="section-divider"></div>
        </div>

        {loading ? (
          <div className="center-loader">
            <Loader />
          </div>
        ) : filteredNews.length > 0 ? (
          <div className="news-grid">
            {filteredNews.map((article, index) => (
              <div className="news-card" key={index}>
                <div className="news-card-gradient"></div>
                {article.urlToImage && (
                  <div 
                    className="news-image" 
                    style={{ backgroundImage: `url(${article.urlToImage})` }}
                  />
                )}
                <div className="news-card-content">
                  <div className="news-meta">
                    <span className="news-category">{article.category || 'Umum'}</span>
                    <span className="news-date">{formatDate(article.publishedAt)}</span>
                  </div>
                  <h2 className="news-title">{article.title}</h2>
                  <p className="news-description">{article.description}</p>
                  <div className="news-source">
                    {article.source && article.source.name && (
                      <span>Sumber: {article.source.name}</span>
                    )}
                  </div>
                  <a 
                    href={article.url} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="read-more-btn"
                  >
                    Baca Selengkapnya
                  </a>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="no-news-found">
            <h3>Tidak ada berita yang ditemukan</h3>
            <p>Coba ubah filter atau kata kunci pencarian Anda</p>
          </div>
        )}
      </section>
    </div>
  );
};

// Sample news data as fallback
const sampleNewsData = [
  {
    title: "Bank Indonesia Pertahankan Suku Bunga Acuan di Level 5,75%",
    description: "Rapat Dewan Gubernur (RDG) Bank Indonesia pada 20-21 Mei 2025 memutuskan untuk mempertahankan suku bunga BI Rate di level 5,75%, sesuai dengan upaya stabilisasi nilai tukar Rupiah dan pengendalian inflasi.",
    url: "https://example.com/news1",
    urlToImage: "https://picsum.photos/id/1/600/400",
    publishedAt: "2025-05-21T13:30:00Z",
    source: { name: "Ekonomi Indonesia" },
    category: "economy"
  },
  {
    title: "Indeks Harga Saham Gabungan Menguat 1,2% Ditopang Sektor Perbankan",
    description: "IHSG ditutup menguat 1,2% ke level 8.250 pada perdagangan hari ini, ditopang oleh penguatan saham-saham perbankan setelah laporan keuangan Q1 yang positif.",
    url: "https://example.com/news2",
    urlToImage: "https://picsum.photos/id/2/600/400",
    publishedAt: "2025-05-20T15:45:00Z",
    source: { name: "Bursa News" },
    category: "market"
  },
  {
    title: "PT Telkom Indonesia Umumkan Ekspansi Jaringan 5G ke 15 Kota Baru",
    description: "TLKM mengumumkan rencana ekspansi jaringan 5G ke 15 kota baru pada tahun 2025, sebagai bagian dari strategi transformasi digital nasional.",
    url: "https://example.com/news3",
    urlToImage: "https://picsum.photos/id/3/600/400",
    publishedAt: "2025-05-19T09:15:00Z",
    source: { name: "Tech Daily" },
    category: "technology"
  },
  {
    title: "Rupiah Menguat ke Rp 15.250 per Dolar AS Seiring Aliran Modal Asing",
    description: "Nilai tukar rupiah terhadap dolar AS menguat ke level Rp 15.250 pada perdagangan hari ini, didukung oleh aliran modal asing yang masuk ke pasar obligasi dan saham.",
    url: "https://example.com/news4",
    urlToImage: "https://picsum.photos/id/4/600/400",
    publishedAt: "2025-05-18T11:20:00Z",
    source: { name: "Berita Finansial" },
    category: "finance"
  },
  {
    title: "Bank Central Asia Raih Penghargaan Bank Terbaik Asia Tenggara 2025",
    description: "PT Bank Central Asia Tbk (BBCA) meraih penghargaan 'Best Bank in Southeast Asia 2025' dari Asian Banker, berkat inovasi digital dan pertumbuhan yang konsisten.",
    url: "https://example.com/news5",
    urlToImage: "https://picsum.photos/id/5/600/400",
    publishedAt: "2025-05-17T14:50:00Z",
    source: { name: "Bisnis Update" },
    category: "business"
  }
];

export default NewsPage;
